import xarray as xr
import numpy as np
from satpy.readers.fci_l2_nc import FciL2NCAMVFileHandler

def test_fci_l2_nc_amv_units_bug():
    # Mocking the file handler
    # We need to mock the nc property and filename_info
    class MockHandler(FciL2NCAMVFileHandler):
        def __init__(self):
            self.filename = "test.nc"
            self.filename_info = {"channel": "test_channel"}
            # Mock the nc property
            self._nc = xr.Dataset(
                {"var": (("number_of_images", "number_of_winds"), np.zeros((10, 10)), {"unit": "m/s"})},
                attrs={"platform": "MTG", "data_source": "FCI"}
            )
        @property
        def nc(self):
            return self._nc

    handler = MockHandler()
    dataset_info = {"nc_key": "var"}
    variable = handler.get_dataset("test_id", dataset_info)

    # The bug: 'unit' is still there, and 'units' is missing
    # If the bug is present, this assertion will pass.
    # We want to show that 'units' is NOT present.
    assert "unit" in variable.attrs
    assert "units" not in variable.attrs
    print("Bug reproduced: 'unit' attribute is present and 'units' is missing.")

if __name__ == "__main__":
    test_fci_l2_nc_amv_units_bug()

